 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width horizontal marks encode a repeating sequence by row residue.
    horizontal = {}
    for r, row in enumerate(grid):
        vals = {v for v in row if v != 0}
        if len(vals) == 1 and all(v != 0 for v in row):
            horizontal[r] = row[0]
    if horizontal:
        period = len(horizontal)
        cycle = {}
        for r, color in horizontal.items():
            cycle[r % period] = color
        # Every residue occurs in the examples; fill defensively if not.
        fallback = next(iter(cycle.values()))
        return [[cycle.get(r % period, fallback)] * w for r in range(h)]

    # Diagonal stripes run down-right. Their signed offsets c-r, folded modulo
    # the number of distinct stripes, define a periodic diagonal color pattern.
    offsets = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in offsets and offsets[d] != color:
                    # Input can contain touching shapes; keep the first mark.
                    continue
                offsets[d] = color
    period = len(offsets)
    if period == 0:
        return [[0] * w for _ in range(h)]
    cycle = {}
    for d, color in offsets.items():
        cycle[d % period] = color
    fallback = next(iter(cycle.values()))
    return [[cycle.get((c - r) % period, fallback) for c in range(w)]
            for r in range(h)]
